    const c = new URL(u.href);
    Array.from(c.searchParams.keys()).forEach(k => { if (/^(utm_|gclid|fbclid|gbraid|wbraid|msclkid|ved$|sa$)/i.test(k)) c.searchParams.delete(k); });
